custom_fields.summary:
[[[

const va = states[variables.var_assistsat_entity]?.attributes || {};
const weatherState = states[va.weather_entity || 'weather.home'];
const attrs = weatherState?.attributes || {};
const available = weatherState && !['unknown','unavailable'].includes(weatherState.state);
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number = v => v !== null && v !== undefined && v !== '' && Number.isFinite(Number(v));
const value = (v, unit) => available && number(v) ? esc(Number(v).toLocaleString(undefined, {maximumFractionDigits:1})) + esc(unit) : '—';
const labels = {sunny:'Sunny', 'clear-night':'Clear night', partlycloudy:'Partly cloudy', cloudy:'Cloudy', rainy:'Rainy', pouring:'Heavy rain', snowy:'Snowy', 'snowy-rainy':'Sleet', lightning:'Thunderstorms', 'lightning-rainy':'Thundery rain', windy:'Windy', 'windy-variant':'Windy', fog:'Foggy', hail:'Hail', exceptional:'Exceptional weather'};
const condition = available ? (labels[weatherState.state] || weatherState.state.replace(/[-_]/g,' ')) : 'Weather unavailable';
const icon = available ? (variables.var_weather_icon || 'mdi:weather-cloudy') : 'mdi:weather-cloudy-alert';
return `<div class="clock-weather"><ha-icon icon="${esc(icon)}"></ha-icon><div class="clock-current"><div class="clock-temp">${value(attrs.temperature, attrs.temperature_unit || '°')}</div><div class="clock-condition">${esc(condition)} · View forecast</div></div><div class="clock-metric"><div class="clock-metric-label">WIND</div><div class="clock-metric-value">${value(attrs.wind_speed, attrs.wind_speed_unit ? ' ' + attrs.wind_speed_unit : '')}</div></div><div class="clock-metric"><div class="clock-metric-label">HUMIDITY</div><div class="clock-metric-value">${value(attrs.humidity, '%')}</div></div><span class="clock-link" aria-hidden="true">↗</span></div>`;

]]]

variables.var_url_params:
[[[
  let queryString = '';
  const vaEntity = hass.states[variables.var_assistsat_entity];

  if (vaEntity?.attributes?.current_path) {
    const currentPath = vaEntity.attributes.current_path;
    queryString = currentPath.includes('?') ? currentPath.split('?')[1] : '';
  }

  if (!queryString && window.location.search) {
    queryString = window.location.search.substring(1);
  }

  return new URLSearchParams(queryString);
]]]

variables.var_camera:
[[[
  const urlParams = variables.var_url_params;
  const urlCamera = urlParams.get('camera');
  const showAll = urlParams.get('show');

  if (showAll === 'all' || showAll === 'configured') {
    return "";
  }

  if (urlCamera) {
    return urlCamera;
  }

  const availableCameras = [];
  const cameraKeys = Object.keys(hass.states).filter(id => id.startsWith('camera.'));

  for (let i = 0; i < cameraKeys.length; i++) {
    const entityId = cameraKeys[i];
    const state = hass.states[entityId].state;
    if (state !== 'unavailable' && state !== 'unknown') {
      availableCameras.push(entityId);
    }
  }

  if (availableCameras.length === 1) {
    return availableCameras[0];
  }

  return "";
]]]

variables.var_all_cameras:
[[[
  const formatCameraName = (entityId) => {
    return entityId.replace('camera.', '').replace(/_/g, ' ');
  };

  const isCameraAvailable = (state) => {
    return state !== 'unavailable' && state !== 'unknown';
  };

  const urlParams = variables.var_url_params;
  const showType = urlParams.get('show');
  const configuredCameras = urlParams.get('cameras');

  if (showType === 'configured' && configuredCameras) {
    const cameras = [];
    const cameraEntityList = decodeURIComponent(configuredCameras).split(',');

    for (let i = 0; i < cameraEntityList.length; i++) {
      const entityId = cameraEntityList[i].trim();
      const entity = hass.states[entityId];
      if (entity && isCameraAvailable(entity.state)) {
        cameras.push({
          entity_id: entityId,
          name: entity.attributes.friendly_name || formatCameraName(entityId)
        });
      }
    }
    return cameras;
  }

  const viewAssistEntity = variables.var_assistsat_entity;

  if (viewAssistEntity && hass.states[viewAssistEntity]) {
    const cameraList = hass.states[viewAssistEntity].attributes.camera_list;

    if (Array.isArray(cameraList)) {
      const cameras = [];

      for (let i = 0; i < cameraList.length; i++) {
        const entityId = cameraList[i];
        const entity = hass.states[entityId];
        if (entity && isCameraAvailable(entity.state)) {
          cameras.push({
            entity_id: entityId,
            name: entity.attributes.friendly_name || formatCameraName(entityId)
          });
        }
      }

      if (cameras.length > 0) {
        return cameras;
      }
    }
  }

  const cameras = [];
  const cameraKeys = Object.keys(hass.states).filter(id => id.startsWith('camera.'));

  for (let i = 0; i < cameraKeys.length; i++) {
    const entityId = cameraKeys[i];
    const entity = hass.states[entityId];
    if (isCameraAvailable(entity.state)) {
      cameras.push({
        entity_id: entityId,
        name: entity.attributes.friendly_name || formatCameraName(entityId)
      });
    }
  }

  cameras.sort((a, b) => a.name.localeCompare(b.name));
  return cameras;
]]]

